rows['023'].push(
['afghanistan-landlocked','Easy','country','is landlocked and lies west of Pakistan','स्थलरुद्ध है और पाकिस्तान के पश्चिम में स्थित है','ਭੂ-ਬੱਧ ਹੈ ਅਤੇ ਪਾਕਿਸਤਾਨ ਦੇ ਪੱਛਮ ਵੱਲ ਸਥਿਤ ਹੈ',['Afghanistan','Bangladesh','SriLanka','Maldives'],0,'Afghanistan has no coastline and borders Pakistan to its east and southeast.','अफ़ग़ानिस्तान का समुद्री तट नहीं है और इसकी पूर्वी तथा दक्षिण-पूर्वी सीमा पाकिस्तान से लगती है।','ਅਫ਼ਗਾਨਿਸਤਾਨ ਦਾ ਸਮੁੰਦਰੀ ਤਟ ਨਹੀਂ ਅਤੇ ਇਸਦੀ ਪੂਰਬੀ ਤੇ ਦੱਖਣ-ਪੂਰਬੀ ਸਰਹੱਦ ਪਾਕਿਸਤਾਨ ਨਾਲ ਲੱਗਦੀ ਹੈ।',['WGE-PHY-023A']],
['brahmaputra-tibet-name','Hard','river','rises on the Tibetan Plateau, where its upper course is called the Yarlung Tsangpo','तिब्बती पठार से निकलती है, जहाँ इसका ऊपरी भाग यारलुंग त्सांगपो कहलाता है','ਤਿੱਬਤੀ ਪਠਾਰ ਤੋਂ ਨਿਕਲਦਾ ਹੈ, ਜਿੱਥੇ ਇਸਦਾ ਉੱਪਰਲਾ ਰਸਤਾ ਯਾਰਲੁੰਗ ਸਾਂਗਪੋ ਕਹਾਉਂਦਾ ਹੈ',['Brahmaputra','Indus','Ganges','Jamuna'],0,'The Brahmaputra begins as the Yarlung Tsangpo on the Tibetan Plateau before flowing east and then turning south.','ब्रह्मपुत्र तिब्बती पठार पर यारलुंग त्सांगपो के रूप में निकलती है, फिर पूर्व और बाद में दक्षिण की ओर मुड़ती है।','ਬ੍ਰਹਮਪੁੱਤਰ ਤਿੱਬਤੀ ਪਠਾਰ ਉੱਤੇ ਯਾਰਲੁੰਗ ਸਾਂਗਪੋ ਵਜੋਂ ਨਿਕਲਦਾ ਹੈ, ਫਿਰ ਪੂਰਬ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਦੱਖਣ ਵੱਲ ਮੁੜਦਾ ਹੈ।',['WGE-PHY-023B']],
['ganges-brahmaputra-delta','Medium','river','joins the Ganges river system in Bangladesh before reaching the Bay of Bengal','बंगाल की खाड़ी तक पहुँचने से पहले बांग्लादेश में गंगा नदी-तंत्र से मिलती है','ਬੰਗਾਲ ਦੀ ਖਾੜੀ ਤੱਕ ਪਹੁੰਚਣ ਤੋਂ ਪਹਿਲਾਂ ਬੰਗਲਾਦੇਸ਼ ਵਿੱਚ ਗੰਗਾ ਦਰਿਆਈ ਤੰਤਰ ਨਾਲ ਮਿਲਦਾ ਹੈ',['Brahmaputra','Indus','Kabul','Jamuna'],0,'The Ganges and Brahmaputra systems combine in Bangladesh and form a vast delta at the Bay of Bengal.','गंगा और ब्रह्मपुत्र नदी-तंत्र बांग्लादेश में मिलकर बंगाल की खाड़ी पर विशाल डेल्टा बनाते हैं।','ਗੰਗਾ ਅਤੇ ਬ੍ਰਹਮਪੁੱਤਰ ਦਰਿਆਈ ਤੰਤਰ ਬੰਗਲਾਦੇਸ਼ ਵਿੱਚ ਮਿਲ ਕੇ ਬੰਗਾਲ ਦੀ ਖਾੜੀ ਕੋਲ ਵਿਸ਼ਾਲ ਡੈਲਟਾ ਬਣਾਉਂਦੇ ਹਨ।',['WGE-PHY-023B']],
['china-nepal-north','Easy','country','lies north of Nepal across the Himalaya','हिमालय के पार नेपाल के उत्तर में स्थित है','ਹਿਮਾਲਿਆ ਦੇ ਪਾਰ ਨੇਪਾਲ ਦੇ ਉੱਤਰ ਵੱਲ ਸਥਿਤ ਹੈ',['China','Pakistan','Bangladesh','Myanmar'],0,'China borders Nepal along the Himalayan arc to Nepal’s north.','चीन नेपाल की उत्तरी हिमालयी सीमा से लगता है।','ਚੀਨ ਨੇਪਾਲ ਦੀ ਉੱਤਰੀ ਹਿਮਾਲਿਆਈ ਸਰਹੱਦ ਨਾਲ ਲੱਗਦਾ ਹੈ।',['WGE-PHY-023A']],
['india-myanmar-east','Medium','country','lies east of India and connects South Asia with mainland Southeast Asia','भारत के पूर्व में है और दक्षिण एशिया को मुख्यभूमि दक्षिण-पूर्व एशिया से जोड़ता है','ਭਾਰਤ ਦੇ ਪੂਰਬ ਵੱਲ ਹੈ ਅਤੇ ਦੱਖਣੀ ਏਸ਼ੀਆ ਨੂੰ ਮੁੱਖਭੂਮੀ ਦੱਖਣ-ਪੂਰਬੀ ਏਸ਼ੀਆ ਨਾਲ ਜੋੜਦਾ ਹੈ',['Myanmar','Nepal','Afghanistan','Maldives'],0,'Myanmar borders India to the west and forms a land connection toward mainland Southeast Asia.','म्यांमार भारत से पश्चिम में सीमा साझा करता है और मुख्यभूमि दक्षिण-पूर्व एशिया की ओर स्थल-संपर्क बनाता है।','ਮਿਆਂਮਾਰ ਭਾਰਤ ਨਾਲ ਪੱਛਮ ਵੱਲ ਸਰਹੱਦ ਸਾਂਝੀ ਕਰਦਾ ਹੈ ਅਤੇ ਮੁੱਖਭੂਮੀ ਦੱਖਣ-ਪੂਰਬੀ ਏਸ਼ੀਆ ਵੱਲ ਧਰਤੀ ਦਾ ਜੋੜ ਬਣਾਉਂਦਾ ਹੈ।',['WGE-PHY-023A']],
['bangladesh-delta-setting','Hard','country','occupies the lower Ganges–Brahmaputra delta at the head of the Bay of Bengal','बंगाल की खाड़ी के शीर्ष पर निचले गंगा–ब्रह्मपुत्र डेल्टा में स्थित है','ਬੰਗਾਲ ਦੀ ਖਾੜੀ ਦੇ ਸਿਰੇ ਉੱਤੇ ਹੇਠਲੇ ਗੰਗਾ–ਬ੍ਰਹਮਪੁੱਤਰ ਡੈਲਟਾ ਵਿੱਚ ਸਥਿਤ ਹੈ',['Bangladesh','Nepal','Bhutan','Afghanistan'],0,'Much of Bangladesh lies on the low-lying delta formed by the Ganges, Brahmaputra and Meghna river systems.','बांग्लादेश का बड़ा भाग गंगा, ब्रह्मपुत्र और मेघना नदी-तंत्रों से बने निचले डेल्टा पर है।','ਬੰਗਲਾਦੇਸ਼ ਦਾ ਵੱਡਾ ਹਿੱਸਾ ਗੰਗਾ, ਬ੍ਰਹਮਪੁੱਤਰ ਅਤੇ ਮੇਘਨਾ ਦਰਿਆਈ ਤੰਤਰਾਂ ਨਾਲ ਬਣੇ ਨੀਵੇਂ ਡੈਲਟੇ ਉੱਤੇ ਹੈ।',['WGE-PHY-023A','WGE-PHY-023B']]
);
const make=(cp,row,i)=>{const [objective,difficulty,type,ctxE,ctxH,ctxP,opts,correct,factE,factH,factP,sourceIds]=row;const typeText={lake:['Which lake','कौन-सी झील','ਕਿਹੜੀ ਝੀਲ'],waterfall:['Which waterfall','कौन-सा जलप्रपात','ਕਿਹੜਾ ਜਲ-ਪ੍ਰਪਾਤ'],desert:['Which desert','कौन-सा मरुस्थल','ਕਿਹੜਾ ਮਾਰੂਥਲ'],island:['Which island','कौन-सा द्वीप','ਕਿਹੜਾ ਟਾਪੂ'],peninsula:['Which peninsula','कौन-सा प्रायद्वीप','ਕਿਹੜਾ ਪ੍ਰਾਇਦੀਪ'],isthmus:['Which isthmus','कौन-सा स्थलडमरूमध्य','ਕਿਹੜਾ ਭੂ-ਸੰਯੋਜਕ'],cape:['Which cape','कौन-सा अंतरीप','ਕਿਹੜਾ ਅੰਤਰੀਪ'],capital:['Which city','कौन-सा शहर','ਕਿਹੜਾ ਸ਼ਹਿਰ'],landlocked:['Which landlocked country','कौन-सा स्थलरुद्ध देश','ਕਿਹੜਾ ਭੂ-ਬੱਧ ਦੇਸ਼'],islandState:['Which island country','कौन-सा द्वीपीय देश','ਕਿਹੜਾ ਟਾਪੂ-ਦੇਸ਼'],'island-state':['Which island country','कौन-सा द्वीपीय देश','ਕਿਹੜਾ ਟਾਪੂ-ਦੇਸ਼'],enclave:['Which country','कौन-सा देश','ਕਿਹੜਾ ਦੇਸ਼'],transcontinental:['Which country','कौन-सा देश','ਕਿਹੜਾ ਦੇਸ਼'],country:['Which country','कौन-सा देश','ਕਿਹੜਾ ਦੇਸ਼'],territory:['Which territory','कौन-सा क्षेत्र','ਕਿਹੜਾ ਖੇਤਰ'],river:['Which river','कौन-सी नदी','ਕਿਹੜਾ ਦਰਿਆ'],mountain:['Which mountain range','कौन-सी पर्वत-श्रेणी','ਕਿਹੜੀ ਪਹਾੜੀ ਲੜੀ']}[type];if(!Array.isArray(opts)) throw new Error(`Bad options ${cp} ${i}: ${JSON.stringify(row)}`);const tr=k=>{if(!terms[k]) missingChoices.add(k); return [k,terms[k]?.[0]??k,terms[k]?.[1]??k]};const shift=i%4;const rotated=[...opts.slice(shift),...opts.slice(0,shift)];const opts3=[rotated,rotated.map(x=>tr(x)[1]),rotated.map(x=>tr(x)[2])];const correctIndex=(4-shift)%4;const stems=stemOverrides[objective]??[`${typeText[0]} ${ctxE}?`,`${typeText[1]} ${ctxH}?`,`${typeText[2]} ${ctxP}?`];return {id:`WGE-001-CP${cp}-Q${String(i+1).padStart(3,'0')}`,cpId:`WGE-001-CP${cp}`,objective,difficulty,sourceIds,correctIndex,locales:{en:{stem:stems[0],options:opts3[0],explanation:factE},hi:{stem:stems[1],options:opts3[1],explanation:factH},pa:{stem:stems[2],options:opts3[2],explanation:factP}}};};
for(const cp of ['020','021','022','023']) writeFileSync(`artifacts/api-server/src/knowledge-v1/world-geography/cp${cp}.json`,JSON.stringify(rows[cp].map((r,i)=>make(cp,r,i)),null,2)+'\n');
